"""Tool registry with JSON-schema-style argument validation (no dependencies)."""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable


class ToolError(Exception):
    """Raised for any failure the model should be told about (bad args, unknown tool, tool crash)."""


_TYPES: dict[str, tuple[type, ...]] = {
    "string": (str,),
    "integer": (int,),
    "number": (int, float),
    "boolean": (bool,),
    "array": (list,),
    "object": (dict,),
}


def validate(value: Any, schema: dict, path: str = "$") -> list[str]:
    """Return a list of human-readable errors; empty list means valid.
    Supports: type, enum, minimum, maximum, required, properties,
    additionalProperties=false, items."""
    errors: list[str] = []
    t = schema.get("type")
    if t:
        ok = isinstance(value, _TYPES[t])
        if t in ("integer", "number") and isinstance(value, bool):
            ok = False  # bool is an int subclass in Python; reject it
        if not ok:
            return [f"{path}: expected {t}, got {type(value).__name__}"]
    if "enum" in schema and value not in schema["enum"]:
        errors.append(f"{path}: must be one of {schema['enum']}")
    if "minimum" in schema and isinstance(value, (int, float)) and value < schema["minimum"]:
        errors.append(f"{path}: must be >= {schema['minimum']}")
    if "maximum" in schema and isinstance(value, (int, float)) and value > schema["maximum"]:
        errors.append(f"{path}: must be <= {schema['maximum']}")
    if t == "object":
        props = schema.get("properties", {})
        for name in schema.get("required", []):
            if name not in value:
                errors.append(f"{path}.{name}: required")
        if schema.get("additionalProperties") is False:
            for name in value:
                if name not in props:
                    errors.append(f"{path}.{name}: unexpected argument")
        for name, sub in props.items():
            if name in value:
                errors.extend(validate(value[name], sub, f"{path}.{name}"))
    if t == "array" and "items" in schema:
        for i, item in enumerate(value):
            errors.extend(validate(item, schema["items"], f"{path}[{i}]"))
    return errors


@dataclass(frozen=True)
class Tool:
    name: str
    description: str
    schema: dict
    fn: Callable[..., Any]
    writes: bool = False  # True if the tool changes the outside world


class Registry:
    def __init__(self, dry_run: bool = False, max_result_chars: int = 2000) -> None:
        self._tools: dict[str, Tool] = {}
        self.dry_run = dry_run
        self.max_result_chars = max_result_chars

    def register(self, tool: Tool) -> None:
        if tool.name in self._tools:
            raise ValueError(f"duplicate tool {tool.name}")
        self._tools[tool.name] = tool

    def specs(self) -> list[dict]:
        """What the model sees: name, description, parameter schema. Nothing else."""
        return [
            {"name": t.name, "description": t.description, "parameters": t.schema}
            for t in self._tools.values()
        ]

    def call(self, name: str, args: Any) -> str:
        tool = self._tools.get(name)
        if tool is None:
            raise ToolError(f"unknown tool '{name}'. Available: {sorted(self._tools)}")
        problems = validate(args, tool.schema)
        if problems:
            raise ToolError("invalid arguments: " + "; ".join(problems))
        if tool.writes and self.dry_run:
            return f"DRY RUN: {name}({args}) was not executed"
        try:
            result = tool.fn(**args)
        except Exception as exc:  # a crashing tool must not crash the agent
            raise ToolError(f"tool '{name}' failed: {type(exc).__name__}: {exc}") from exc
        text = result if isinstance(result, str) else repr(result)
        if len(text) > self.max_result_chars:
            text = text[: self.max_result_chars] + f"... [truncated {len(text) - self.max_result_chars} chars]"
        return text

"""A framework-free agent loop with hard budgets and loop detection."""
from __future__ import annotations

import json
import time
from collections import Counter
from dataclasses import dataclass, field
from typing import Any, Callable, Protocol

from tools import Registry, ToolError


@dataclass(frozen=True)
class ToolCall:
    id: str
    name: str
    args: Any


@dataclass(frozen=True)
class ModelReply:
    text: str | None = None
    tool_calls: tuple[ToolCall, ...] = ()
    tokens: int = 0  # input + output tokens this call consumed


class Model(Protocol):
    def __call__(self, messages: list[dict], tools: list[dict]) -> ModelReply: ...


@dataclass(frozen=True)
class Budget:
    max_steps: int = 8
    max_tokens: int = 20_000
    max_seconds: float = 30.0
    max_consecutive_errors: int = 3
    max_identical_calls: int = 2  # the third identical call is treated as a loop


@dataclass
class RunResult:
    status: str  # done | max_steps | token_budget | timeout | loop_detected | too_many_errors
    answer: str | None
    steps: int
    tokens: int
    trace: list[dict] = field(default_factory=list)


class Agent:
    def __init__(
        self,
        model: Model,
        registry: Registry,
        budget: Budget = Budget(),
        clock: Callable[[], float] = time.monotonic,
    ) -> None:
        self.model, self.registry, self.budget, self.clock = model, registry, budget, clock

    def run(self, task: str) -> RunResult:
        b = self.budget
        messages: list[dict] = [{"role": "user", "content": task}]
        trace: list[dict] = []
        started = self.clock()
        tokens = 0
        seen: Counter[tuple[str, str]] = Counter()
        consecutive_errors = 0

        def stop(status: str, step: int, answer: str | None = None) -> RunResult:
            trace.append({"event": "stop", "status": status, "step": step})
            return RunResult(status, answer, step, tokens, trace)

        for step in range(1, b.max_steps + 1):
            if self.clock() - started > b.max_seconds:
                return stop("timeout", step - 1)
            reply = self.model(messages, self.registry.specs())
            tokens += reply.tokens
            trace.append({"event": "model", "step": step, "tokens": reply.tokens,
                          "tools": [c.name for c in reply.tool_calls]})
            if tokens > b.max_tokens:
                return stop("token_budget", step)  # no tool runs once over budget
            if not reply.tool_calls:
                return stop("done", step, reply.text)
            messages.append({"role": "assistant", "content": reply.text,
                             "tool_calls": [{"id": c.id, "name": c.name, "args": c.args}
                                            for c in reply.tool_calls]})
            for call in reply.tool_calls:
                signature = (call.name, json.dumps(call.args, sort_keys=True, default=str))
                seen[signature] += 1
                if seen[signature] > b.max_identical_calls:
                    return stop("loop_detected", step)
                try:
                    observation = self.registry.call(call.name, call.args)
                    consecutive_errors = 0
                except ToolError as exc:
                    observation = f"ERROR: {exc}"  # fed back so the model can self-correct
                    consecutive_errors += 1
                trace.append({"event": "tool", "step": step, "name": call.name,
                              "ok": not observation.startswith("ERROR:")})
                messages.append({"role": "tool", "tool_call_id": call.id, "content": observation})
                if consecutive_errors >= b.max_consecutive_errors:
                    return stop("too_many_errors", step)
        return stop("max_steps", b.max_steps)

import pytest

from agent import Agent, Budget, ModelReply, ToolCall
from tools import Registry, Tool, ToolError, validate


class ScriptedModel:
    """Fake model: returns pre-written replies in order and records what it was shown."""

    def __init__(self, replies):
        self.replies = list(replies)
        self.seen: list[list[dict]] = []

    def __call__(self, messages, tools):
        self.seen.append([dict(m) for m in messages])
        if not self.replies:
            raise AssertionError("script exhausted: the agent called the model more than expected")
        return self.replies.pop(0)


def call(name, cid="c1", tokens=10, **args):
    return ModelReply(tool_calls=(ToolCall(cid, name, args),), tokens=tokens)


def say(text, tokens=10):
    return ModelReply(text=text, tokens=tokens)


ADD_SCHEMA = {
    "type": "object",
    "properties": {"a": {"type": "integer"}, "b": {"type": "integer", "minimum": 0}},
    "required": ["a", "b"],
    "additionalProperties": False,
}


@pytest.fixture
def registry():
    r = Registry()
    r.register(Tool("add", "Add two integers", ADD_SCHEMA, lambda a, b: a + b))
    r.register(Tool("boom", "Always fails", {"type": "object"}, lambda: 1 / 0))
    return r


def test_happy_path_returns_answer(registry):
    model = ScriptedModel([call("add", a=2, b=3), say("The sum is 5")])
    result = Agent(model, registry).run("2+3?")
    assert (result.status, result.answer, result.steps) == ("done", "The sum is 5", 2)
    assert model.seen[1][-1] == {"role": "tool", "tool_call_id": "c1", "content": "5"}


def test_invalid_args_are_fed_back_and_model_can_recover(registry):
    model = ScriptedModel([call("add", a="x", b=1), call("add", cid="c2", a=1, b=1), say("2")])
    result = Agent(model, registry).run("add")
    assert result.status == "done"
    assert "$.a: expected integer, got str" in model.seen[1][-1]["content"]


def test_unknown_tool_is_an_error_observation_not_a_crash(registry):
    model = ScriptedModel([call("rm_rf", path="/"), say("sorry")])
    result = Agent(model, registry).run("x")
    assert result.status == "done"
    assert model.seen[1][-1]["content"].startswith("ERROR: unknown tool 'rm_rf'")


def test_tool_exception_becomes_error_observation(registry):
    model = ScriptedModel([call("boom"), say("it failed")])
    assert Agent(model, registry).run("x").status == "done"
    assert "ZeroDivisionError" in model.seen[1][-1]["content"]


def test_max_steps_stops_a_model_that_never_finishes(registry):
    class Endless:
        n = 0

        def __call__(self, messages, tools):
            self.n += 1
            return call("add", cid=str(self.n), a=self.n, b=1)  # always different args

    model = Endless()
    result = Agent(model, registry, Budget(max_steps=4)).run("x")
    assert result.status == "max_steps" and model.n == 4


def test_identical_calls_are_detected_as_a_loop(registry):
    model = ScriptedModel([call("add", cid=str(i), a=1, b=1) for i in range(5)])
    result = Agent(model, registry, Budget(max_identical_calls=2)).run("x")
    assert result.status == "loop_detected"
    assert result.steps == 3  # third identical call trips the detector


def test_token_budget_stops_before_running_the_tool():
    ran = []
    r = Registry()
    r.register(Tool("t", "t", {"type": "object"}, lambda: ran.append(1) or "ok", writes=True))
    model = ScriptedModel([call("t", tokens=5_000)])
    result = Agent(model, r, Budget(max_tokens=1_000)).run("x")
    assert result.status == "token_budget" and ran == []


def test_wall_clock_budget_uses_injected_clock(registry):
    ticks = iter([0.0, 0.0, 100.0])
    model = ScriptedModel([call("add", a=1, b=1), say("never reached")])
    agent = Agent(model, registry, Budget(max_seconds=10), clock=lambda: next(ticks))
    assert agent.run("x").status == "timeout"


def test_consecutive_errors_trip_the_circuit_breaker(registry):
    model = ScriptedModel([call("boom", cid=str(i), ) for i in range(5)])
    # identical calls would trip loop detection first, so vary the budget
    result = Agent(model, registry, Budget(max_identical_calls=10, max_consecutive_errors=3)).run("x")
    assert result.status == "too_many_errors" and result.steps == 3


def test_dry_run_blocks_write_tools():
    sent = []
    r = Registry(dry_run=True)
    r.register(Tool("send_email", "send", {"type": "object", "properties": {"to": {"type": "string"}},
                                          "required": ["to"]}, lambda to: sent.append(to), writes=True))
    model = ScriptedModel([call("send_email", to="a@b.c"), say("done")])
    Agent(model, r).run("x")
    assert sent == [] and "DRY RUN" in model.seen[1][-1]["content"]


def test_validator_rejects_bool_as_integer_and_extra_keys():
    assert validate(True, {"type": "integer"}) == ["$: expected integer, got bool"]
    assert validate({"a": 1, "z": 2}, ADD_SCHEMA)  # missing b and unexpected z

"""A tiny stateful workflow engine: nodes, edges, reducers, JSON checkpoints, interrupts."""
from __future__ import annotations

import json
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable

END = "__end__"
_NO_RESUME = object()


class Interrupt(Exception):
    """Raised inside a node to pause the run and ask a human (or another system)."""

    def __init__(self, payload: Any) -> None:
        super().__init__("interrupt")
        self.payload = payload


class Context:
    """Passed to every node. interrupt() pauses the first time and returns the human's
    answer when the node is re-run on resume."""

    def __init__(self, resume: Any = _NO_RESUME) -> None:
        self._resume = resume

    def interrupt(self, payload: Any) -> Any:
        if self._resume is _NO_RESUME:
            raise Interrupt(payload)
        return self._resume


class JsonCheckpointStore:
    """One JSON file per thread; every super-step appends a checkpoint (history = time travel)."""

    def __init__(self, directory: str | Path) -> None:
        self.dir = Path(directory)
        self.dir.mkdir(parents=True, exist_ok=True)

    def _path(self, thread_id: str) -> Path:
        safe = "".join(c for c in thread_id if c.isalnum() or c in "-_")
        if safe != thread_id or not safe:
            raise ValueError("thread_id must be alphanumeric, '-' or '_'")
        return self.dir / f"{safe}.json"

    def history(self, thread_id: str) -> list[dict]:
        p = self._path(thread_id)
        return json.loads(p.read_text())["checkpoints"] if p.exists() else []

    def latest(self, thread_id: str) -> dict | None:
        h = self.history(thread_id)
        return h[-1] if h else None

    def save(self, thread_id: str, checkpoint: dict) -> None:
        data = {"checkpoints": self.history(thread_id) + [checkpoint]}
        tmp = self._path(thread_id).with_suffix(".tmp")
        tmp.write_text(json.dumps(data, indent=2))
        os.replace(tmp, self._path(thread_id))  # atomic: a crash never leaves a half-written file


@dataclass
class RunResult:
    status: str  # done | interrupted
    state: dict
    interrupt: Any = None


class Graph:
    def __init__(self, reducers: dict[str, Callable[[Any, Any], Any]] | None = None,
                 max_steps: int = 50) -> None:
        self.nodes: dict[str, Callable[[dict, Context], dict]] = {}
        self.edges: dict[str, str] = {}
        self.routers: dict[str, Callable[[dict], str]] = {}
        self.entry: str | None = None
        self.reducers = reducers or {}
        self.max_steps = max_steps

    def add_node(self, name: str, fn: Callable[[dict, Context], dict]) -> None:
        self.nodes[name] = fn
        self.entry = self.entry or name

    def add_edge(self, src: str, dst: str) -> None:
        self.edges[src] = dst

    def add_conditional_edges(self, src: str, router: Callable[[dict], str]) -> None:
        self.routers[src] = router

    def _merge(self, state: dict, update: dict) -> dict:
        merged = dict(state)
        for key, value in update.items():
            reducer = self.reducers.get(key)
            merged[key] = reducer(state.get(key), value) if reducer else value  # default: overwrite
        return merged

    def _next(self, node: str, state: dict) -> str:
        if node in self.routers:
            return self.routers[node](state)
        return self.edges.get(node, END)

    def run(self, thread_id: str, store: JsonCheckpointStore,
            input: dict | None = None, resume: Any = _NO_RESUME) -> RunResult:
        ckpt = store.latest(thread_id)
        if ckpt is None:
            state, node, status = dict(input or {}), self.entry, "running"
            store.save(thread_id, {"state": state, "next": node, "status": status})
        else:
            state, node, status = ckpt["state"], ckpt["next"], ckpt["status"]
        if status == "done":
            return RunResult("done", state)
        for _ in range(self.max_steps):
            ctx = Context(resume)
            resume = _NO_RESUME  # a resume value answers only the node that was paused
            try:
                update = self.nodes[node](state, ctx)
            except Interrupt as it:
                store.save(thread_id, {"state": state, "next": node,
                                       "status": "interrupted", "pending": it.payload})
                return RunResult("interrupted", state, it.payload)
            state = self._merge(state, update or {})
            node = self._next(node, state)
            status = "done" if node == END else "running"
            store.save(thread_id, {"state": state, "next": node, "status": status})
            if node == END:
                return RunResult("done", state)
        raise RuntimeError(f"exceeded max_steps={self.max_steps}: cyclic graph without exit?")

"""Support-refund workflow built on graph.py: lookup -> propose -> (approve) -> execute."""
from __future__ import annotations

from graph import END, Context, Graph

ORDERS = {"A100": {"customer": "c1", "total": 30}, "B200": {"customer": "c2", "total": 120}}
AUTO_APPROVE_LIMIT = 50


class Ledger:
    """Stand-in for a payments API that supports idempotency keys."""

    def __init__(self) -> None:
        self.refunds: dict[str, int] = {}

    def refund(self, key: str, amount: int) -> None:
        self.refunds.setdefault(key, amount)  # same key twice -> still one refund


def build(ledger: Ledger) -> Graph:
    g = Graph(reducers={"log": lambda old, new: (old or []) + new})

    def lookup(state: dict, ctx: Context) -> dict:
        order = ORDERS.get(state["order_id"])
        if order is None:
            return {"error": "unknown order", "log": ["lookup: not found"]}
        return {"order": order, "log": [f"lookup: total={order['total']}"]}

    def propose(state: dict, ctx: Context) -> dict:
        amount = state["order"]["total"]
        return {"proposal": {"action": "refund", "amount": amount},
                "log": [f"propose: refund {amount}"]}

    def approve(state: dict, ctx: Context) -> dict:
        # On resume this whole node runs again from the top, so anything before
        # interrupt() must be safe to repeat.
        decision = ctx.interrupt({"question": "Approve refund?", "proposal": state["proposal"]})
        return {"approved": bool(decision.get("approved")),
                "log": [f"approve: {'yes' if decision.get('approved') else 'no'}"]}

    def execute(state: dict, ctx: Context) -> dict:
        key = f"refund-{state['order_id']}"  # derived from business identity, not from a random id
        ledger.refund(key, state["proposal"]["amount"])
        return {"log": [f"execute: refunded under key {key}"]}

    def reject(state: dict, ctx: Context) -> dict:
        return {"log": ["reject: no refund issued"]}

    for name, fn in [("lookup", lookup), ("propose", propose), ("approve", approve),
                     ("execute", execute), ("reject", reject)]:
        g.add_node(name, fn)
    g.add_conditional_edges("lookup", lambda s: END if "error" in s else "propose")
    g.add_conditional_edges(
        "propose", lambda s: "execute" if s["proposal"]["amount"] <= AUTO_APPROVE_LIMIT else "approve")
    g.add_conditional_edges("approve", lambda s: "execute" if s["approved"] else "reject")
    g.add_edge("execute", END)
    g.add_edge("reject", END)
    return g

"""Tool permission policy: default deny, explicit allow, ask-above-threshold."""
from __future__ import annotations

POLICY = {
    "get_order": {"mode": "allow"},
    "search_docs": {"mode": "allow"},
    "refund": {"mode": "ask_above", "field": "amount", "limit": 50},
    "delete_account": {"mode": "ask"},
}


def decide(tool: str, args: dict, policy: dict = POLICY) -> str:
    """Return 'allow', 'ask' (needs human approval) or 'deny'."""
    rule = policy.get(tool)
    if rule is None:
        return "deny"  # unknown tools are never callable
    mode = rule["mode"]
    if mode == "allow":
        return "allow"
    if mode == "ask":
        return "ask"
    if mode == "ask_above":
        value = args.get(rule["field"])
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            return "deny"  # cannot evaluate the threshold -> fail closed
        return "ask" if value > rule["limit"] else "allow"
    return "deny"

"""A minimal MCP server speaking JSON-RPC 2.0 over stdio (newline-delimited messages).
Targets the 2025-06-18 / 2025-11-25 revisions (initialize handshake). Check the spec
revision your client negotiates: the 2026-07-28 revision removes the handshake."""
from __future__ import annotations

import json
import sys

PROTOCOL_VERSION = "2025-06-18"
ORDERS = {"A100": "shipped", "B200": "processing"}

TOOLS = [{
    "name": "get_order_status",
    "description": "Look up the status of one order by id. Read-only.",
    "inputSchema": {
        "type": "object",
        "properties": {"order_id": {"type": "string"}},
        "required": ["order_id"],
        "additionalProperties": False,
    },
}]


def _ok(req_id, result):
    return {"jsonrpc": "2.0", "id": req_id, "result": result}


def _err(req_id, code, message):
    return {"jsonrpc": "2.0", "id": req_id, "error": {"code": code, "message": message}}


def _call_tool(req_id, params):
    name, args = params.get("name"), params.get("arguments") or {}
    if name != "get_order_status":
        return _err(req_id, -32602, f"Unknown tool: {name}")  # protocol error
    order_id = args.get("order_id")
    if not isinstance(order_id, str) or set(args) - {"order_id"}:
        # Bad arguments are a tool execution error (isError) so the model can self-correct.
        return _ok(req_id, {"content": [{"type": "text", "text": "order_id (string) is required"}],
                            "isError": True})
    status = ORDERS.get(order_id)
    text = f"Order {order_id}: {status}" if status else f"No order {order_id}"
    return _ok(req_id, {"content": [{"type": "text", "text": text}], "isError": status is None})


def handle(msg: dict):
    """Pure function: one JSON-RPC message in, one response (or None for notifications) out."""
    method, req_id = msg.get("method"), msg.get("id")
    if req_id is None:
        return None  # notifications (e.g. notifications/initialized) get no response
    if method == "initialize":
        return _ok(req_id, {
            "protocolVersion": PROTOCOL_VERSION,
            "capabilities": {"tools": {"listChanged": False}},
            "serverInfo": {"name": "orders-demo", "version": "0.1.0"},
        })
    if method == "ping":
        return _ok(req_id, {})
    if method == "tools/list":
        return _ok(req_id, {"tools": TOOLS})
    if method == "tools/call":
        return _call_tool(req_id, msg.get("params") or {})
    return _err(req_id, -32601, f"Method not found: {method}")


def main() -> None:
    for line in sys.stdin:  # one JSON message per line; never print anything else to stdout
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except json.JSONDecodeError:
            print(json.dumps(_err(None, -32700, "Parse error")), flush=True)
            continue
        reply = handle(msg)
        if reply is not None:
            print(json.dumps(reply), flush=True)


if __name__ == "__main__":
    main()

"""Runtime enforcement: tool allowlist, budgets, kill switch, and the 'lethal trifecta' rule."""
from __future__ import annotations

import time
from dataclasses import dataclass
from typing import Callable

from guard import Decision


class BudgetExceeded(Exception):
    pass


@dataclass(frozen=True)
class ToolRule:
    reads_private: bool = False      # touches data the user/tenant owns
    external_comm: bool = False      # can send data out (email, HTTP, ticket comment visible to others)
    max_calls: int = 5
    allowed_recipient_domains: frozenset[str] = frozenset()


class RunBudget:
    def __init__(self, max_tokens: int = 20_000, max_tool_calls: int = 10, max_seconds: float = 30.0,
                 clock: Callable[[], float] = time.monotonic) -> None:
        self.max_tokens, self.max_tool_calls, self.max_seconds = max_tokens, max_tool_calls, max_seconds
        self.clock, self.started = clock, clock()
        self.tokens = self.tool_calls = 0

    def charge_tokens(self, n: int) -> None:
        self.tokens += n
        self.check()

    def charge_tool_call(self) -> None:
        self.tool_calls += 1
        self.check()

    def check(self) -> None:
        if self.tokens > self.max_tokens:
            raise BudgetExceeded("token budget")
        if self.tool_calls > self.max_tool_calls:
            raise BudgetExceeded("tool-call budget")
        if self.clock() - self.started > self.max_seconds:
            raise BudgetExceeded("time budget")


class ToolGate:
    def __init__(self, rules: dict[str, ToolRule], budget: RunBudget,
                 kill_switch: Callable[[], bool] = lambda: False) -> None:
        self.rules, self.budget, self.kill_switch = rules, budget, kill_switch
        self.counts: dict[str, int] = {}
        self.untrusted_seen = False  # set when untrusted content entered the context
        self.private_read = False   # set once a private-data tool was authorised

    def mark_untrusted(self) -> None:
        self.untrusted_seen = True

    def authorize(self, tool: str, args: dict) -> Decision:
        if self.kill_switch():
            return Decision(False, "kill switch is on")
        rule = self.rules.get(tool)
        if rule is None:
            return Decision(False, f"tool '{tool}' is not allowlisted")
        if self.counts.get(tool, 0) >= rule.max_calls:
            return Decision(False, f"per-tool limit reached for '{tool}'")
        try:
            self.budget.charge_tool_call()
        except BudgetExceeded as exc:
            return Decision(False, f"budget exceeded: {exc}")
        if rule.external_comm:
            if self.untrusted_seen and self.private_read:
                return Decision(False, "blocked: private data + untrusted content + outbound channel")
            domain = str(args.get("to", "")).rpartition("@")[2].lower()
            if domain not in rule.allowed_recipient_domains:
                return Decision(False, f"recipient domain '{domain}' is not allowed")
        self.counts[tool] = self.counts.get(tool, 0) + 1
        if rule.reads_private:
            self.private_read = True
        return Decision(True, "ok")

"""Score an agent run (its trace) against a test case: outcome, tool-call accuracy, trajectory rules."""
from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Case:
    id: str
    must_call: tuple[str, ...] = ()        # tools that must appear
    must_not_call: tuple[str, ...] = ()    # tools that must never appear (e.g. send_email on injected docs)
    max_steps: int = 8
    answer_contains: tuple[str, ...] = ()
    answer_must_not_contain: tuple[str, ...] = ()


def score(case: Case, tool_calls: list[str], answer: str, steps: int) -> dict[str, bool]:
    """tool_calls is the ordered list of tool names from the trace."""
    return {
        "called_required": all(t in tool_calls for t in case.must_call),
        "avoided_forbidden": not any(t in tool_calls for t in case.must_not_call),
        "within_steps": steps <= case.max_steps,
        "answer_ok": all(s.lower() in answer.lower() for s in case.answer_contains)
        and not any(s.lower() in answer.lower() for s in case.answer_must_not_contain),
    }


def passed(result: dict[str, bool]) -> bool:
    return all(result.values())


def pass_rate(results: list[dict[str, bool]]) -> float:
    return sum(passed(r) for r in results) / len(results) if results else 0.0
